import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation that uses a bit array and multiple hash functions
    to probabilistically determine if an item is in a set. The size of the bit array
    and the number of hash functions are calculated based on the expected number of
    items and the desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        if expected_items <= 0 or not (0 < false_positive_rate < 1):
            raise ValueError("Invalid parameters: expected_items must be > 0 and false_positive_rate must be between 0 and 1.")

        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate the optimal size of the bit array (m) and number of hash functions (k)
        self.bit_array_size = self._get_optimal_bit_array_size(expected_items, false_positive_rate)
        self.num_hashes = self._get_optimal_number_of_hashes(self.bit_array_size, expected_items)

        # Initialize a bit array with all bits set to 0
        self.bit_array = [0] * self.bit_array_size

    def _get_optimal_bit_array_size(self, n: int, p: float) -> int:
        """ Calculate the optimal size of the bit array (m). """
        m = - (n * math.log(p)) / (math.log(2) ** 2)
        return math.ceil(m)

    def _get_optimal_number_of_hashes(self, m: int, n: int) -> int:
        """ Calculate the optimal number of hash functions (k). """
        k = (m / n) * math.log(2)
        return math.ceil(k)

    def _hashes(self, item: str) -> list:
        """ Generate k hash values for the given item. """
        hash_values = []
        for i in range(self.num_hashes):
            hash_value = hashlib.md5(f"{item}{i}".encode()).hexdigest()
            hash_values.append(int(hash_value, 16) % self.bit_array_size)
        return hash_values

    def add(self, item: str) -> None:
        """ Add an item to the Bloom Filter. """
        for hash_index in self._hashes(item):
            self.bit_array[hash_index] = 1

    def contains(self, item: str) -> bool:
        """ Check if an item is in the Bloom Filter. """
        return all(self.bit_array[hash_index] for hash_index in self._hashes(item))

