    A Bloom Filter implementation utilizing a list of boolean values for the bit array.
    It calculates the size and number of hash functions needed based on expected items 
    and false positive rate, providing efficient membership testing while allowing
    for false positives and no false negatives.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
