        self.num_hashes = self._calculate_hash_functions(self.bit_array_size, expected_items)

        self.bit_array = [False] * self.bit_array_size

    def _calculate_bit_array_size(self, n: int, p: float) -> int:
        """ Calculate the optimal size of the bit array (m) using the formula based on n and p. """
        m = -(n * math.log(p)) / (math.log(2) ** 2)
        return math.ceil(m)

    def _calculate_hash_functions(self, m: int, n: int) -> int:
        """ Calculate the optimal number of hash functions (k) using the formula based on m and n. """
        k = (m / n) * math.log(2)
        return math.ceil(k)

