        """ Create a deterministic hash based on the item and a seed by using SHA-256. """
        hash_input = f"{item}:{seed}".encode('utf-8')
        return int(hashlib.sha256(hash_input).hexdigest(), 16) % self.bit_array_size

    def _get_hash_indexes(self, item: str) -> list:
        """ Retrieve multiple hash indexes for the given item using the predetermined number of hashes. """
        return [self._hash_item(item, i) for i in range(self.num_hashes)]

    def add(self, item: str) -> None:
        """ Add an item to the Bloom Filter by setting the corresponding bits to True. """
        for index in self._get_hash_indexes(item):
            self.bit_array[index] = True

    def contains(self, item: str) -> bool:
        """ Check whether an item is possibly in the Bloom Filter by verifying the bits are all True. """
        return all(self.bit_array[index] for index in self._get_hash_indexes(item))
